
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_vmt84_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_vmt84_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.304670213561001e+00, -4.223021254412672e+00, -4.108729633651553e+00, -3.950656298388012e+00, -3.735787623020436e+00, -3.450929630992703e+00, -3.086643683578826e+00, -2.644224679106117e+00, -2.144269596605386e+00, -1.625083869234422e+00, -1.103228071378506e+00, -7.106271656779762e-01, -6.021858775657413e-01, -5.018450132434040e-01, -3.724797278764776e-01, -2.480398828301280e-01, -1.402894203949663e-01, -4.242340055647735e-02, -5.199760189165534e-03, -2.217931260488251e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


